package com.landportal.repository; import com.landportal.entity.*; import org.springframework.data.jpa.repository.*; import java.util.*; public interface AcquisitionCaseRepository extends JpaRepository<AcquisitionCase,Long>{Optional<AcquisitionCase> findByCaseNumber(String n); List<AcquisitionCase> findByParcelDistrictIgnoreCase(String district); @Query("select distinct c from AcquisitionCase c join Ownership o on o.parcel=c.parcel where o.user.id=:uid") List<AcquisitionCase> findForOwner(Long uid);}
